package com.exampro.controller;import com.exampro.dto.ApiDtos.*;import com.exampro.service.ExamService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class ExamController {private final ExamService s;public ExamController(ExamService s){this.s=s;}@GetMapping("/exams") public List<ExamResponse> all(){return s.all();}@GetMapping("/exams/{id}") public ExamResponse get(@PathVariable Long id){return s.get(id);}@GetMapping("/exams/{id}/questions") public List<QuestionResponse> examQuestions(@PathVariable Long id){return s.examQuestions(id);}@GetMapping("/admin/exams/{id}/questions") public List<AdminQuestionResponse> adminExamQuestions(@PathVariable Long id){return s.adminExamQuestions(id);}@PostMapping("/admin/exams") public ResponseEntity<ExamResponse> create(@Valid @RequestBody ExamRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@PutMapping("/admin/exams/{id}") public ExamResponse update(@PathVariable Long id,@Valid @RequestBody ExamRequest r){return s.update(id,r);}@PostMapping("/admin/exams/{id}/questions") public ExamResponse assign(@PathVariable Long id,@Valid @RequestBody AssignQuestionsRequest r){return s.assign(id,r);}@DeleteMapping("/admin/exams/{id}/questions/{questionId}") public ExamResponse unassign(@PathVariable Long id,@PathVariable Long questionId){return s.unassign(id,questionId);}@DeleteMapping("/admin/exams/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
